class Solution {
public:
    vector<int> nextGreaterElements(vector<int>& nums) {
        int n = nums.size();
        vector<int> res(n, -1);
        vector<int> st;
        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;
            while (!st.empty() && nums[st.back()] < nums[idx]) {
                res[st.back()] = nums[idx];
                st.pop_back();
            }
            if (i < n) st.push_back(i);
        }
        return res;
    }
};

class Solution {
    public int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        Arrays.fill(res, -1);
        int[] st = new int[n];
        int top = 0;
        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;
            while (top > 0 && nums[st[top - 1]] < nums[idx]) {
                res[st[--top]] = nums[idx];
            }
            if (i < n) st[top++] = i;
        }
        return res;
    }
}

var nextGreaterElements = function(nums) {
    const n = nums.length;
    const res = new Array(n).fill(-1);
    const st = [];
    for (let i = 0; i < 2 * n; i++) {
        const idx = i % n;
        while (st.length > 0 && nums[st[st.length - 1]] < nums[idx]) {
            res[st.pop()] = nums[idx];
        }
        if (i < n) st.push(i);
    }
    return res;
};
